def parity_checksum(bits: list[int]) -> int:
    """
    এই ফাংশনটি একটি তালিকা `bits` এর জন্য `parity_checksum` নামে একটি ফাংশন সংজ্ঞায়িত করে।
    এটি `bits` এর মধ্যে 1 এর সংখ্যা গণনা করে এবং যদি সংখ্যাটি জোড় হয় তবে 0 রিটার্ন করে, অন্যথায় 1 রিটার্ন করে।
    যদি তালিকাটি খালি হয় তবে 0 রিটার্ন করে।
    """
    count = 0
    for bit in bits:
        count += bit
    if count % 2 == 0:
        return 0
    else:
        return 1

