    """
    একটি নতুন list return করে, যেখানে `nums`-এর প্রতিটা number `low` থেকে `high` পর্যন্ত (দুই bound সহ) range-এর ভেতরে আটকে দেওয়া হয়:
    `low`-এর চেয়ে ছোট number হয়ে যায় `low`, `high`-এর চেয়ে বড় number হয়ে যায় `high`, বাকিগুলো যেমন আছে তেমনই থাকে।
    আগের order-টা ঠিক থাকবে।
    """
    result = []
    for num in nums:
        if num < low:
            result.append(low)
        elif num > high:
            result.append(high)
        else:
            result.append(num)
    return result

