def count_subsequence_matches(text: str, sub: str) -> int:
    n = len(text)
    m = len(sub)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 1
    for j in range(1, m + 1):
        dp[0][j] = 1
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if text[i - 1] == sub[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
    return dp[n][m]

