def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    """
    `n` by `n` chessboard-এ `n`-টা queen এমনভাবে বসানোর উপায়ের সংখ্যা return করবে, যাতে কোনো দুটো queen একে অপরকে attack না করে (কোনো দুটো একই row, একই column বা একই diagonal-এ না থাকে) এবং কোনো queen `blocked`-এ থাকা কোনো square-এ না থাকে। square-গুলো `(row, column)` pair, যার index 0 থেকে শুরু (0-based)। কোনো blocked square শুধু তাতে queen বসানো নিষিদ্ধ করে; এটা তার ভেতর দিয়ে queen-দের attack আটকায় না। board-এর বাইরে থাকা `blocked`-এর entry ignore করা হবে। `n` সমান 0 হলে ঠিক একটা placement (empty placement) আছে, তাই result 1।

    শুধু complete code-টা একটা Python code block-এ দিন।
    """
    if n == 0:
        return 1

    # blocked squares
    blocked_set = set()
    for row, col in blocked:
        blocked_set.add((row, col))

    # blocked squares in the board
    for row, col in blocked_set:
        if row < n and col < n:
            return 0

    # queen placement
    return count_queens(n - 1, blocked_set)

