def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    result = []
    for i in range(1 << len(nums)):
        subset = []
        sum_of_subset = 0
        for j in range(len(nums)):
            if (i >> j) & 1:
                subset.append(nums[j])
                sum_of_subset += nums[j]
        if sum_of_subset == k:
            result.append(subset)
    return result

