def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    queue = [(0, 0, 0)]
    visited = set()
    visited.add((0, 0))
    while queue:
        x, y, path_length = queue.pop(0)
        if x == rows - 1 and y == cols - 1:
            return path_length
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                queue.append((nx, ny, path_length + 1))
                visited.add((nx, ny))
    return -1

