def parse_csv(text: str) -> list[list[str]]:
    """
    CSV text-কে record-এর list-এ parse করবে, প্রতিটা record হলো field string-এর একটা list।
    একটা record-এর field-গুলো comma দিয়ে আলাদা থাকে আর record-গুলো newline character `\n` দিয়ে আলাদা থাকে।
    যে field double quote `"` দিয়ে শুরু হয় সেটা quoted: এটা পরের এমন double quote-এ শেষ হয় যেটা doubled না, এর ভেতরের comma আর newline সাধারণ character, এবং এর ভেতরে পরপর দুটো double quote একটা double quote character বোঝায়;
    গ্রুপ করা quote-গুলো value-এর অংশ না। Quoted field-এর closing quote-এর পরে সবসময় একটা comma, একটা newline অথবা `text`-এর শেষ থাকে, আর unquoted field-এ কখনো double quote থাকে না।
    Field কখনো trim করা হয় না, তাই space থেকে যায়।
    `text`-এর একদম শেষের newline নতুন record শুরু করে না, একটা empty line একটামাত্র empty string-সহ একটা record দেয়, আর empty `text` থেকে empty list পাওয়া যায়।
    """
    lines = text.split('\n')
    records = []
    for line in lines:
        record = []
        for field in line.split(','):
            if field.startswith('"') and field.endswith('"'):
                record.append(field[1:-1])
            else:
                record.append(field)
        records.append(record)
    return records

