def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    n = len(matrix)
    new_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            new_matrix[j][n - 1 - i] = matrix[i][j]
    for i in range(k, n):
        new_matrix[i][n - 1 - i] = matrix[i - k][n - 1 - i]
