def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    """
    একটি গুদামের কার্যক্রম সিমুলেট করে।
    `events`-এর প্রতিটি ইভেন্ট একটি টাপল `(kind, item, quantity)`, যেখানে `quantity` ধনাত্মক এবং `kind` হয় `'receive'` (`item`-এর ততগুলো একক মজুতে আসে) অথবা `'order'` (কোনো ক্রেতা `item`-এর ততগুলো একক অর্ডার করে)।
    যেসব আইটেম কোনো ইভেন্টে আছে, প্রতিটির মজুত শুরুতে 0।
    কোন অর্ডার তখনই সঙ্গে সঙ্গে পাঠানো হয় এবং মজুত কমে, যখন একই আইটেমের আগের কোনো অর্ডার অপেক্ষায় নেই এবং ওই আইটেমের মজুত অন্তত `quantity`;
    অর্ডারটি পুরোটাই ওই আইটেমের অপেক্ষার সারিতে যোগ হয় (অর্ডার কখনো ভাগ করা হয় না)।
    কোন `'receive'` ইভেন্ট মজুত বাড়ানোর পর, সেই আইটেমের অপেক্ষমাণ অর্ডারগুলো যে ক্রমে দেওয়া হয়েছিল সেই ক্রমে পাঠানো হয়: প্রথম অপেক্ষমাণ অর্ডার মজুতে কুলালে পাঠানো হয়, তারপর পরেরটি, এভাবে চলে, আর মজুতে কুলায় না এমন প্রথম অপেক্ষমাণ অর্ডারে এসে থেমে যায়।
    ফাংশনটি একটি টাপল `(stock, waiting)` ফেরত দেয়, যেখানে `stock` হলো প্রতিটি আইটেম থেকে তার চূড়ান্ত মজুতের ডিকশনারি (মজুত 0 এমন আইটেমসহ) এবং `waiting` হলো এখনো অপেক্ষমাণ অর্ডারগুলোর `(item, quantity)` টাপলের তালিকা, যা অর্ডার দেওয়ার সময় অনুযায়ী (সব আইটেম মিলিয়ে) সাজানো।
    """
    stock = {}
    waiting = []
    for event in events:
        kind, item, quantity = event
        stock[item] = stock.get(item, 0) + quantity
        waiting.append((item, quantity))
    return (stock, waiting)

