def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    result = []

    for instruction in program:
        if instruction == 'PUSH':
            stack.append(int(instruction.split()[1]))
        elif instruction == 'POP':
            stack.pop()
        elif instruction == 'DUP':
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'ADD':
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'SUB':
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'MUL':
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'JMP':
            t = int(instruction.split()[2])
            if t < len(stack):
                stack.insert(t, stack.pop())
            else:
                next_instruction = program[t]
                if next_instruction == 'HALT':
                    break
                else:
                    next_instruction = next_instruction.split()[0]
                stack.insert(0, stack.pop())
        elif instruction == 'JZ':
            t = int(instruction.split()[2])
            if t < len(stack):
                stack.insert(t, stack.pop())
            else:
                next_instruction = program[t]
                if next_instruction == 'HALT':
                    break
                else:
                    next_instruction = next_instruction.split()[0]
                stack.insert(0, stack.pop())
        elif instruction == 'HALT':
            break
        else:
            raise ValueError("Invalid instruction")

    while stack:
        result.append(stack.pop())

    return result

