def run_stack_program(program: list[str]) -> list[int] | None:
    """
    একটি ছোট মেশিনে প্যাকড স্ট্যাক প্রোগ্রাম চালানোর জন্য একটি Python ফাংশন লিখুন।
    প্যাকেডটি প্যাকড স্ট্যাকের চূড়ান্ত মান ফেরত দেয়, প্যাকড স্ট্যাকের ভিত্তি থেকে উপরের দিকে।
    `program` হল স্ট্যাকের ইনস্ট্রাকশনগুলির একটি তালিকা; মেশিনটি খালি প্যাকড স্ট্যাক এবং প্যাকড স্ট্যাকের সূচক 0 দিয়ে শুরু হয়।
    ইনস্ট্রাকশনগুলি হল: `PUSH n` (n এর মানটি প্যাক করুন, যা নেতিবাচকও হতে পারে), `POP` (প্যাকড স্ট্যাক থেকে উপরের মানটি সরান), `DUP` (n এর কপিটি প্যাক করুন), `SWAP` (দুটি মানের মধ্যে পরিবর্তন করুন), `ADD`, `SUB` এবং `MUL` (n এর মানটি সরান, তারপর পরবর্তী মানটি যোগ করুন, বিয়োগ করুন বা গুণ করুন), `JMP t` (n এর সূচক `t` এর সাথে চালিয়ে যান), এবং `JZ t` (n এর সূচক `t` 0 হলে, অন্যথায় পরবর্তী ইনস্ট্রাকশনের সূচক চালিয়ে যান)।
    অন্য কোনও ইনস্ট্রাকশন চলতে থাকলে, পরবর্তী ইনস্ট্রাকশন চালিয়ে যান।
    যখন প্যাকড স্ট্যাকের সূচক `len(program)` এর চেয়ে কম হয়, তখন প্যাকড স্ট্যাকের চূড়ান্ত মান ফেরত দিন।
    যদি একটি ইনস্ট্রাকশন আরও মান প্রয়োজন হয়, বা প্রোগ্রাম চলতে থাকে 1000 বার (যা 1000 বার লুপের জন্য), তাহলে `None` ফেরত দিন।
    """
    stack = []
    for instruction in program:
        if instruction == 'PUSH':
            stack.append(int(instruction.split()[1]))
        elif instruction == 'POP':
            if stack:
                stack.pop()
        elif instruction == 'DUP':
            stack.append(stack.pop())
        elif instruction == 'SWAP':
            if stack:
                stack.append(stack.pop())
                stack.append(stack.pop())
        elif instruction == 'ADD':
            if stack:
                stack.append(stack.pop())
                stack.append(stack.pop())
        elif instruction == 'SUB':
            if stack:
                stack.append(stack.pop())
                stack.append(stack.pop())
        elif instruction == 'MUL':
            if stack:
                stack.append(stack.pop())
                stack.append(stack.pop())
        elif instruction == 'JMP':
            if stack:
                stack.append(int(instruction.split()[1]))
        elif instruction == 'JZ':
            if stack:
                stack.append(int(instruction.split()[1]))
    if stack:
        return stack
    else:
        return None

